'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number.isFinite(+n)?(+n).toLocaleString('en-GB',{maximumFractionDigits:d}):'—';
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
let date=(x,short=false)=>new Date(x).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
let clock=x=>new Date(x).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const local=x=>{const d=new Date(x||Date.now());return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const defaults=()=>({schema:2,entries:[],measurements:[],vials:[],reminders:[],feelings:[],batches:[],profile:{},settings:{theme:'system',color:'#087e88',detailed:true,half:6,showWeight:true,showMacros:true,showEstimate:true},onboarded:false});
let S,loadError='',page='overview',undo=null,chart=null,importData=null,calendarRows=[],healthRows=[],csvData=null,selectedSite='',selectedVial='';
try{const raw=window.Native?Native.readStore():localStorage.getItem('reta-log');S=raw?Core.validateStore(JSON.parse(raw)):defaults();S={...defaults(),...S,settings:{...defaults().settings,...S.settings}};}catch(e){loadError='Your saved data could not be read. It has not been overwritten. '+e.message;S=defaults();}
function persist(){if(loadError)throw Error(loadError);Core.validateStore(S);const raw=JSON.stringify(S);if(window.Native){if(!Native.saveStore(raw))throw Error('Storage could not be saved.');}else localStorage.setItem('reta-log',raw);}
function change(fn,undoable=false){const before=JSON.stringify(S);try{fn();persist();if(undoable)undo=before;return true;}catch(e){S=JSON.parse(before);toast(e.message);return false;}}
function toast(msg,canUndo=false){$('#toast').innerHTML=`<span>${esc(msg)}</span>${canUndo?'<button onclick="undoLast()">Undo</button>':''}`;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),canUndo?15000:5000);}
function undoLast(){if(!undo)return;const current=JSON.stringify(S);try{S=JSON.parse(undo);persist();if(window.Native)Native.scheduleReminders(JSON.stringify(S.reminders));undo=null;render();toast('Change undone.');}catch(e){S=JSON.parse(current);toast(e.message);}}
function applyTheme(){const dark=S.settings.theme==='dark'||(S.settings.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.body.classList.toggle('dark',dark);document.documentElement.style.setProperty('--accent',S.settings.color);if(window.Native)Native.setBars(dark);}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{applyTheme();if(chart)chart.draw();});
function navigate(p){closeModal();page=p;document.body.classList.remove('full-chart');chart=null;render();window.scrollTo(0,0);}
function header(title,sub){return `<div class="brand"><span class="logo">${icon('drop')}</span><span>Reta Log<small style="display:block">YOUR PERSONAL JOURNAL</small></span><span class="grow"></span><button class="round" aria-label="Settings" onclick="navigate('settings')">${icon('settings')}</button></div><h1>${title}</h1><p class="muted">${sub}</p>`;}
const card=(body,cls='',id='')=>`<section ${id?'id="'+esc(id)+'"':''} class="card ${cls}">${body}</section>`;
const button=(label,action,cls='primary')=>`<button class="${cls}" onclick="${esc(action)}">${label}</button>`;
function field(id,label,value='',type='text'){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" ${type==='number'?'step="any" inputmode="decimal"':''} value="${esc(value)}">`;}
function select(id,label,options,value){return `<label for="${id}">${label}</label><select id="${id}">${options.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('')}</select>`;}
function modal(title,html){$('#modal').innerHTML=`<div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="handle"></div><div class="sheet-head"><h2>${title}</h2><button onclick="closeModal()" aria-label="Close">×</button></div><div id="form-error" class="error"></div>${html}</div>`;}
function closeModal(){$('#modal').innerHTML='';}
function formError(e){const el=$('#form-error');if(el)el.textContent=e.message||e;else toast(e.message||e);}
const val=id=>$('#'+id).value;
function render(){applyTheme();const pages={overview:overview,journal:journal,insights:insights,calculator:calculator,profile:profile,settings:settings,learn:learn,inventory:inventory,data:dataPage,reminders:reminders,wellness:wellness,legal:legalPage,summary:summaryPage};$('#app').innerHTML=`<main>${(pages[page]||overview)()}</main><nav>${[['overview','home','Overview'],['journal','journal','Journal'],['insights','chart','Insights'],['calculator','calc','Calc'],['profile','user','Profile']].map(([p,i,n])=>`<button aria-label="${p==='calculator'?'Calculator':n}" title="${p==='calculator'?'Calculator':n}" ${p===page?'aria-current="page"':''} class="${p===page?'active':''}" onclick="navigate('${p}')">${icon(i)}<span>${n}</span></button>`).join('')}</nav>`;if(page==='insights'){setupChart();setupWeightChart();}if(page==='overview')drawMini();if(loadError)toast(loadError);}
function latestWeight(){return [...S.measurements].filter(m=>m.values.weight).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];}
function overview(){const actual=S.entries.filter(e=>!e.status||e.status==='taken').sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)),ds=Core.doses(actual),last=actual[0],w=latestWeight(),recent=actual.filter(e=>Date.parse(e.at)>=Date.now()-7*Core.DAY).reduce((a,e)=>a+ +e.mg,0);let html=header(S.profile.name?'Hello, '+esc(S.profile.name.split(' ')[0])+'.':'A clearer daily picture.','Your history, progress and patterns. In one place.');
html+=doseWindowCard()+weeklyCard();
html+=`<div class="stats">${card(`<div class="eyebrow">Latest entry</div><div class="stat">${last?fmt(last.mg)+' mg':'—'}</div><div class="hint">${last?date(last.at,true)+' · '+clock(last.at):'Start your journal'}</div>`)}${card(`<div class="eyebrow">${S.settings.showWeight?'Latest weight':'Total entries'}</div><div class="stat">${S.settings.showWeight?(w?fmt(w.values.weight)+' kg':'—'):actual.length}</div><div class="hint">${w&&S.settings.showWeight?date(w.at,true):'Your private record'}</div>`)}</div>`;
html+=button('+ Log an entry','editEntry()');if(S.settings.showEstimate&&ds.length)html+=card(`<div class="row spread"><div><div class="eyebrow">Model estimate · now</div><div class="stat">${fmt(Core.amount(ds,Date.now(),S.settings.half))} mg</div></div>${icon('chart')}</div><p class="hint">Estimated amount remaining right now from your confirmed entries, using a ${fmt(S.settings.half)}-day half-life. This is a point on the model curve as it falls from a peak towards a trough, not the average of those two values.</p><p class="hint">The 24-hour average and view average are separate chart lines. This is a mathematical estimate, not a measured amount in your body or blood.</p>`);
if(S.settings.showMacros&&(S.profile.protein||S.profile.macroMode==='auto'))html+=nutritionCard();
html+=`<div class="section row spread"><h2>Your toolkit</h2><span class="badge">ON DEVICE</span></div><div class="stats">${card(`<div class="row">${icon('box')}<h3>Supplies</h3></div><p class="hint">Vials & pen cartridges</p>${button('Open inventory',"navigate('inventory')",'secondary')}`)}${card(`<div class="row">${icon('learn')}<h3>Learn</h3></div><p class="hint">Understand your equipment</p>${button('Visual guide',"navigate('learn')",'secondary')}`)}</div>`;
html+=forecastPanel();html+=button('How are you feeling today?','editFeeling()','secondary');return html;}
function drawMini(){const canvas=$('#mini');if(!canvas)return;const ratio=devicePixelRatio||1,w=canvas.clientWidth,h=85;canvas.width=w*ratio;canvas.height=h*ratio;const c=canvas.getContext('2d');c.scale(ratio,ratio);const a=Core.doses(S.entries),now=new Date();now.setHours(0,0,0,0);const bars=Array.from({length:7},(_,i)=>{const t=+now-(6-i)*Core.DAY;return a.filter(x=>x.t>=t&&x.t<t+Core.DAY).reduce((s,d)=>s+d.mg,0);}),max=Math.max(1,...bars);bars.forEach((v,i)=>{const x=i*w/7+8,bw=w/7-16,bh=Math.max(3,v/max*45);c.fillStyle=i===6?'#85e4d8':'#386378';c.beginPath();c.roundRect(x,53-bh,bw,bh,4);c.fill();c.fillStyle='#a3c1cf';c.font='12px sans-serif';c.textAlign='center';c.fillText(new Date(+now-(6-i)*Core.DAY).toLocaleDateString('en',{weekday:'narrow'}),x+bw/2,76);});}
function journal(){let html=header('Your journal','Every entry has a place in your story.');html+=`<div class="row">${button('+ Log entry','editEntry()')}${button('Reminders',"navigate('reminders')",'secondary')}</div>`;const sorted=[...S.entries].sort((a,b)=>Core.entryOrder(b,a));if(!sorted.length)html+=card(`<div class="empty">${vialArt()}<h2>Your first entry starts here</h2><p class="muted">Add any past date, amount and optional notes.</p></div>`);sorted.forEach(e=>{html+=card(`<div class="entry"><div class="datebox">${new Date(e.at).toLocaleDateString('en',{month:'short'})}<b>${new Date(e.at).getDate()}</b></div><div class="grow"><div class="value">${fmt(e.mg)} <span class="muted" style="font-size:14px">mg</span></div><div class="hint">${new Date(e.at).toLocaleDateString('en-GB',{weekday:'long'})}<br>${date(e.at)} · ${clock(e.at)}</div></div><button class="edit" aria-label="Edit entry" onclick="editEntry('${e.id}')">${icon('edit')}</button></div>${e.status&&e.status!=='taken'?`<span class="pill">${esc(e.status)}</span>`:''}${e.site?`<p class="hint">${esc(e.site.replaceAll('-',' '))}</p>`:''}${e.note?`<p>${esc(e.note)}</p>`:''}${journalSupply(e)}${S.settings.detailed?`<div class="hint">${esc(e.source||'Manual')}${e.vial?' · '+esc(S.vials.find(v=>v.id===e.vial)?.name||'Archived supply'):''}</div>`:''}`,'journal-entry','entry-'+e.id);});html+=button('Import from calendar',"openCalendar()",'secondary');return html;}
function journalSupply(e){
 if(!e.vial)return '<div class="supply-balance hint">No supply linked · Edit this entry to select a vial or pen cartridge.</div>';
 const v=S.vials.find(v=>v.id===e.vial);if(!v)return '<div class="supply-balance hint">Linked supply is unavailable.</div>';
 const planned=e.status==='planned',taken=!e.status||e.status==='taken',b=planned?Core.supplyBalance(v,S.entries):Core.supplyBalanceAfter(v,S.entries,e);
 const caption=planned?'mg left now':taken?'mg left after this entry':'mg left at this time';
 return `<button type="button" class="supply-balance supply-link" onclick="openSupply('${v.id}','${e.id}')" aria-label="Open ${esc(v.name)} in inventory"><span class="row spread"><span><span class="hint">${v.type==='cartridge'?'Pen cartridge':'Vial'} · ${esc(v.name)}</span><span class="stat supply-number">${fmt(b.remaining)} <small>${caption}</small></span></span>${icon('arrow')}</span><span class="hint supply-note">${fmt(b.used)} of ${fmt(b.declared)} mg logged as taken ${planned?'so far':'up to this entry'}.${planned?' Planned amount is not deducted.':!taken?' Skipped amount is not deducted.':''}${b.overdrawn?' Recorded use exceeds supply by '+fmt(b.overdrawn)+' mg.':''}</span><span class="supply-open">View this supply →</span></button>`;
}
function openSupply(id){
 if(!S.vials.some(v=>v.id===id)){toast('This supply is no longer available.');return;}
 navigate('inventory');requestAnimationFrame(()=>{const el=document.getElementById('supply-'+id);if(!el)return;el.classList.add('supply-focused');el.setAttribute('tabindex','-1');el.scrollIntoView({block:'start'});el.focus({preventScroll:true});});
}
function chooseSite(id){selectedSite=id;$('#torso').innerHTML=torsoArt(id,true);$('#site').value=id.replaceAll('-',' ');}
function editEntry(id){const e=S.entries.find(x=>x.id===id)||{};selectedSite=e.site||'';modal(id?'Edit entry':'New entry',`${field('entry-at','Date & time',local(e.at),'datetime-local')}${field('entry-mg','Recorded amount · mg',e.mg??'','number')}${select('entry-status','Entry status',[['taken','Taken'],['planned','Planned scenario'],['skipped','Skipped']],e.status||'taken')}${select('entry-vial','Supply',[['','Not linked'],...S.vials.filter(v=>v.type!=='water').map(v=>[v.id,v.name+' · '+v.type])],e.vial||'')}<label>Record an abdominal location</label><div id="torso">${torsoArt(selectedSite,true)}</div><div class="hint">Schematic location log, not a clinical injection guide. Your left/right are labelled.</div>${field('site','Injection site · optional',e.site||'')}<label for="note">Notes</label><textarea id="note">${esc(e.note||'')}</textarea>${button('Save entry',`saveEntry('${id||''}')`)}${id?button('Delete entry',`deleteEntry('${id}')`,'danger'):''}`);}
function saveEntry(id){try{const at=new Date(val('entry-at')).toISOString(),mg=Core.positive(val('entry-mg'),'Amount'),status=val('entry-status');if(status==='taken'&&Date.parse(at)>Date.now())throw Error('A taken entry cannot be in the future. Choose Planned instead.');const duplicate=S.entries.find(e=>e.id!==id&&e.status!== 'skipped'&&Math.abs(Date.parse(e.at)-Date.parse(at))<3600000&&+e.mg===mg);if(duplicate&&!confirm('A similar amount is recorded within one hour. Save this as a separate entry?'))return;const old=S.entries.find(x=>x.id===id);const entry={...old,id:id||uid(),at,mg,status,site:val('site').trim(),note:val('note').trim(),vial:val('entry-vial'),source:old?.source||'Manual'};if(change(()=>{S.entries=S.entries.filter(x=>x.id!==id);S.entries.push(entry);},true)){closeModal();render();toast('Entry saved.',true);}}catch(e){formError(e);}}
function deleteEntry(id){if(!confirm('Delete this entry? You can undo the deletion.'))return;if(change(()=>S.entries=S.entries.filter(e=>e.id!==id),true)){closeModal();render();toast('Entry deleted.',true);}}
function editFeeling(){modal('Daily check-in',`${field('feeling-at','Date & time',local(),'datetime-local')}${['Appetite','Nausea','Energy','Mood','Libido','Digestion'].map(n=>select('feel-'+n,n,[['','Not recorded'],[1,'1 · Very low'],[2,'2 · Low'],[3,'3 · Moderate'],[4,'4 · High'],[5,'5 · Very high']],'')).join('')}<p class="hint">For nausea and digestion, rate symptom intensity. These notes show timing, not proof of a drug effect.</p><label for="feeling-note">Custom log / optional note</label><textarea id="feeling-note" rows="6" placeholder="Energy, appetite, sleep, training or anything else you noticed…"></textarea>${button('Save check-in','saveFeeling()')}`);}
function saveFeeling(){try{const at=new Date(val('feeling-at')).toISOString();if(Date.parse(at)>Date.now())throw Error('Choose a current or past date.');const values={};['Appetite','Nausea','Energy','Mood','Libido','Digestion'].forEach(n=>{if(val('feel-'+n))values[n]=+val('feel-'+n);});if(change(()=>S.feelings.push({id:uid(),at,values,note:val('feeling-note')}),true)){closeModal();toast('Check-in saved.',true);}}catch(e){formError(e);}}
function calculator(){return header('Make the numbers clear.','A visual concentration and volume calculator.')+card(`<div class="eyebrow">01 / Your values</div><h2>Concentration & volume</h2>${field('cm','Amount in vial · mg','','number')}${field('cv','Final solution volume · mL','','number')}${field('cd','Amount to convert · mg','','number')}${button('Calculate volume →','calculate()')}`)+card(`<div class="eyebrow">Calculated volume</div><div class="big" id="calc-result">— <small>mL</small></div><p class="hint" id="calc-detail">Enter values above to see the calculation.</p>`,'hero')+card(`<div class="eyebrow">02 / Device illustration</div><div class="chipbar"><button id="syr-tab" class="on" onclick="deviceTab(false)">Syringe</button><button id="pen-tab" onclick="deviceTab(true)">Pen cartridge</button></div><div id="capacity-wrap">${select('capacity','Illustrated capacity',[[.3,'0.3 mL'],[.5,'0.5 mL'],[1,'1 mL'],[3,'3 mL']],1)}</div><div id="device-art">${syringeArt()}</div><p class="hint" id="device-note">Illustrative mL scale, not insulin units. Check the scale of your actual device.</p><button class="link" onclick="navigate('learn')">What do these markings mean? →</button>`)+card(`<div class="eyebrow">03 / Alternative calculation</div><h2>Find final volume</h2>${field('fm','Amount in vial · mg','','number')}${field('fc','Specified concentration · mg/mL','','number')}${button('Calculate final volume','finalCalc()','secondary')}<div class="stat" id="final-result">— mL</div><p class="hint">Final volume is not automatically the amount of bacteriostatic water to add.</p>`)+card(`<h3>A calculation, not a preparation guide.</h3><p class="hint">Use verified instructions for the specific preparation. These calculations do not establish solvent suitability, sterility, stability or a safe dose. Retatrutide is investigational. Illustrations are schematic; values are rounded.</p>`);}
let calcValue=null,penView=false;
function calculate(){try{const r=Core.concentration(val('cm'),val('cv'),val('cd'));calcValue=r.ml;$('#calc-result').innerHTML=fmt(r.ml,4)+' <small>mL</small>';$('#calc-detail').textContent=fmt(r.c,4)+' mg/mL · Volume = amount ÷ concentration';deviceTab(penView);}catch(e){toast(e.message);}}
function deviceTab(pen){penView=pen;$('#syr-tab').classList.toggle('on',!pen);$('#pen-tab').classList.toggle('on',pen);$('#capacity-wrap').style.display=pen?'none':'';$('#device-art').innerHTML=pen?penArt():syringeArt(+val('capacity'),calcValue);$('#device-note').textContent=pen?'Generic pen. Clicks and dial settings are device-specific and cannot be inferred from mL here.':'Illustrative mL scale, not insulin units. Minor marks are '+(+val('capacity')===3?'0.1':+val('capacity')===1?'0.02':'0.01')+' mL. Do not round an amount to a mark using this illustration.';}
function finalCalc(){try{$('#final-result').textContent=fmt(Core.positive(val('fm'))/Core.positive(val('fc')),4)+' mL';}catch(e){toast(e.message);}}
document.addEventListener('input',e=>{if(['cm','cv','cd'].includes(e.target.id)){calcValue=null;$('#calc-result').innerHTML='— <small>mL</small>';$('#calc-detail').textContent='Values changed. Calculate again.';deviceTab(penView);}if(['fm','fc'].includes(e.target.id))$('#final-result').textContent='— mL';});document.addEventListener('change',e=>{if(e.target.id==='capacity')deviceTab(false);});
function insights(){const w=selectedWeightRecords();return header('See the bigger picture.','Explore patterns across time, at your pace.')+`<div class="chipbar">${[7,30,90,0].map(n=>`<button onclick="chartRange(${n})" ${n===30?'class="on"':''}>${n||'All'}${n?'D':''}</button>`).join('')}<button onclick="chartToday()">Today</button></div>`+card(`<div class="chart-controls"><div><div class="eyebrow" style="margin:0">Estimated amount · mg</div><span class="hint" id="chart-range"></span></div><div><button onclick="chartZoom(1.5)" aria-label="Zoom in">+</button> <button onclick="chartZoom(1/1.5)" aria-label="Zoom out">−</button> <button onclick="toggleFull()" aria-label="Full screen"><svg class="icon" viewBox="0 0 24 24"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button></div></div><canvas id="pk-chart" aria-label="Interactive model estimate chart. Drag to pan; pinch to zoom."></canvas><div class="legend"><span><i class="dot" style="background:#26aeb3"></i>Model</span><span><i class="dot" style="background:#c18deb"></i>24h avg</span><span><i class="dot" style="background:#dcad55"></i>7-day trend</span><span>--- View average</span><span><i class="dot" style="background:#ee7eaa"></i>Weight · kg (right)</span></div><div class="chart-value" id="chart-value">Drag to pan · pinch to zoom · tap for a value</div>`,'chart-card')+card(`<div class="row spread"><h3>Chart layers</h3><span class="badge">ESTIMATE</span></div>${[['peaks','Peaks & troughs'],['daily','Trailing 24-hour average'],['trend','Trailing 7-day average'],['average','Time-weighted view average'],['weight','Measured weight · kg (right axis)'],['planned','Include planned scenarios']].map(([k,l])=>`<label class="check"><input type="checkbox" id="layer-${k}" ${k!=='planned'?'checked':''} onchange="chart.draw()">${l}</label>`).join('')}<p class="hint">Model = estimated amount at a specific time, not the average of peak and trough. Peaks and troughs mark the model highs and lows; average lines summarise a time period. Weight uses a separate, labelled right-hand scale. Each weight dot follows your daily weight preference; days without weigh-ins have no dot. Zoom in to see exact kg labels beside each dot. Tap a dot to prioritise its label; all original readings are preserved.</p><p class="hint">The model assumes immediate absorption and exponential elimination with a ${fmt(S.settings.half)}-day half-life. Peaks occur immediately in this simplified model, not necessarily in your body. Missing earlier doses affect the estimate. It cannot measure blood concentration or guide dosing.</p>`)+card(`<div class="row spread"><h2>Body / weight trend</h2><button class="link" onclick="bodyHistory()">View all →</button></div>${w.length?`<div class="big">${fmt(w[w.length-1].values.weight)} <small>kg</small></div><p class="hint">Latest: ${date(w[w.length-1].at)} · ${clock(w[w.length-1].at)}<br>${w.length} daily weights · ${fmt(w[w.length-1].values.weight-w[0].values.weight)} kg since ${date(w[0].at)}</p>${weightChartMarkup()}`:`<p class="muted">Connect Health Connect or import your Eufy history to see progress.</p>`}${button('Add measurement','editMeasurement()','secondary')}`)+card(`<h2>Daily check-ins</h2>${S.feelings.length?[...S.feelings].reverse().slice(0,14).map(f=>`<div class="list-item"><div class="row spread"><b>${dayDate(f.at)}</b><button class="link" onclick="removeFeeling('${f.id}')">Delete</button></div><p class="hint">${Object.entries(f.values).map(([k,v])=>esc(k)+': '+v+'/5').join(' · ')}</p>${esc(f.note||'')}</div>`).join(''):'<p class="muted">Notice how you feel over time.</p>'}${button('Add check-in','editFeeling()','secondary')}`);}
function bodySpark(records){
 const rows=Core.weightDays(records);if(!rows.length)return '';
 const first=new Date(rows[0].t),last=new Date(rows.at(-1).t),a=+new Date(first.getFullYear(),first.getMonth(),1),b=+new Date(last.getFullYear(),last.getMonth()+1,1),months=(last.getFullYear()-first.getFullYear())*12+last.getMonth()-first.getMonth()+1;
 const width=Math.min(6500,Math.max(330,months*76+70)),left=47,right=18,top=24,bottom=177,min=Math.floor(Math.min(...rows.map(r=>r.weight))-1),max=Math.ceil(Math.max(...rows.map(r=>r.weight))+1),X=t=>left+(t-a)/(b-a)*(width-left-right),Y=v=>bottom-(v-min)/(max-min)*(bottom-top);
 let body='<text x="12" y="14" fill="currentColor" font-size="11">kg</text>';
 for(let i=0;i<=4;i++){const v=min+(max-min)*i/4,y=Y(v);body+=`<path d="M${left} ${y}H${width-right}" stroke="var(--line)"/><text x="${left-8}" y="${y+4}" text-anchor="end" fill="currentColor" font-size="11">${fmt(v,1)}</text>`;}
 const stride=Math.max(1,Math.ceil(months/80));
 for(let i=0;i<months;i+=stride){const d=new Date(first.getFullYear(),first.getMonth()+i,1),x=X(+d);body+=`<path d="M${x} ${top}V${bottom}" stroke="var(--line)" stroke-dasharray="3 4"/><text x="${x+3}" y="198" fill="currentColor" font-size="11">${d.toLocaleDateString('en-GB',{month:'short'})}</text><text x="${x+3}" y="213" fill="var(--muted)" font-size="10">${d.getFullYear()}</text>`;}
 body+=`<path d="${rows.map((r,i)=>(i?'L':'M')+X(r.t)+','+Y(r.weight)).join(' ')}" stroke="var(--accent)" stroke-width="2" fill="none"/>`;
 rows.forEach((r,i)=>body+=`<g tabindex="0" role="button" aria-label="${date(r.t)}, ${fmt(r.weight)} kilograms" onclick="weightDetails(${r.t})" onkeydown="if(event.key==='Enter')weightDetails(${r.t})"><circle cx="${X(r.t)}" cy="${Y(r.weight)}" r="12" fill="transparent"/><circle cx="${X(r.t)}" cy="${Y(r.weight)}" r="3.5" fill="var(--accent)"/><title>${date(r.t)} · ${fmt(r.weight)} kg · ${r.count} readings</title></g>`);
 const axis=`<svg class="body-fixed-axis" viewBox="0 0 47 225" aria-label="Kilogram scale"><rect width="47" height="225" fill="var(--card)"/><text x="12" y="14" fill="currentColor" font-size="11">kg</text>${Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return `<text x="39" y="${Y(v)+4}" text-anchor="end" fill="currentColor" font-size="11">${fmt(v,1)}</text>`;}).join('')}</svg>`;
 return `<div class="body-chart-frame">${axis}<div class="body-chart-scroll"><svg role="img" aria-label="Weight in kilograms by calendar month and year" viewBox="0 0 ${width} 225" style="display:block;width:${width}px;min-width:100%;height:225px">${body}</svg></div></div><p class="hint">${date(rows[0].t)} — ${date(rows.at(-1).t)}<br>Tap a dot for dated readings. Dots are daily averages; connecting lines do not imply measurements on missing days.${months>3?' Swipe horizontally to explore months.':''}</p>`;
}
function weightDetails(t){const row=Core.weightDays(S.measurements,S.settings.weightMode).find(r=>r.key===Core.dayKey(t));if(!row)return;modal('Weight · '+date(row.t),`<div class="big">${fmt(row.weight)} <small>kg</small></div><p class="hint">${row.count>1?'Daily average of '+row.count+' readings':'One recorded weigh-in'}</p>${row.rows.map(r=>`<div class="list-item row spread"><span>${date(r.t)} · ${clock(r.t)}</span><b>${fmt(r.weight)} kg</b></div>`).join('')}`);}
function removeFeeling(id){if(confirm('Delete this check-in?')&&change(()=>S.feelings=S.feelings.filter(f=>f.id!==id),true)){render();toast('Check-in deleted.',true);}}
function setupChart(){const canvas=$('#pk-chart');if(!canvas)return;const end=Date.now()+Core.DAY;chart={canvas,start:end-30*Core.DAY,end,draw:drawChart,pointers:new Map(),picked:null};let startX=0,startTime=0,lastMid=0,lastDist=0,moved=false;
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);chart.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});moved=false;startX=e.clientX;startTime=Date.now();lastMid=e.clientX;if(chart.pointers.size===2){const p=[...chart.pointers.values()];lastDist=Math.abs(p[1].x-p[0].x);lastMid=(p[1].x+p[0].x)/2;}};
canvas.onpointermove=e=>{if(!chart.pointers.has(e.pointerId))return;chart.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const span=chart.end-chart.start,w=chart.plotWidth||canvas.clientWidth-110;if(chart.pointers.size===2){moved=true;const p=[...chart.pointers.values()],dist=Math.abs(p[1].x-p[0].x),mid=(p[1].x+p[0].x)/2;if(lastDist>8&&dist>8){const rect=canvas.getBoundingClientRect(),f=Math.max(0,Math.min(1,(mid-rect.left-45)/w)),anchor=chart.start+f*span,newSpan=Math.max(Core.DAY/4,Math.min(5*365*Core.DAY,span*lastDist/dist));chart.start=anchor-f*newSpan;chart.end=chart.start+newSpan;}lastDist=dist;lastMid=mid;}else{if(Math.abs(e.clientX-startX)>4)moved=true;const delta=(e.clientX-lastMid)*span/w;chart.start-=delta;chart.end-=delta;lastMid=e.clientX;}chart.draw();};
canvas.onpointerup=e=>{if(!moved&&Date.now()-startTime<500){const rect=canvas.getBoundingClientRect();chart.picked=chart.start+Math.max(0,Math.min(1,(e.clientX-rect.left-45)/(chart.plotWidth||canvas.clientWidth-110)))*(chart.end-chart.start);const near=(chart.weightPoints||[]).find(r=>Math.abs(r.x-(e.clientX-rect.left))<14);if(near)chart.picked=near.t;if(window.Native)Native.haptic();}chart.pointers.delete(e.pointerId);if(chart.pointers.size===1)lastMid=[...chart.pointers.values()][0].x;chart.draw();};canvas.onpointercancel=e=>chart.pointers.delete(e.pointerId);canvas.onwheel=e=>{e.preventDefault();chartZoom(e.deltaY<0?1.2:1/1.2);};chart.draw();if(matchMedia('(orientation:landscape)').matches&&innerHeight<600){document.body.classList.add('full-chart');setTimeout(()=>chart?.draw(),80);}}
function chartRange(days){if(!chart)return;chart.end=Date.now()+Core.DAY;chart.start=days?chart.end-days*Core.DAY:Math.min(Date.now()-7*Core.DAY,...S.entries.map(e=>Date.parse(e.at)),...Core.weightDays(S.measurements,S.settings.weightMode).map(r=>r.t))-Core.DAY;chart.picked=null;chart.draw();}
function chartToday(){if(!chart)return;const span=chart.end-chart.start;chart.end=Date.now()+Core.DAY;chart.start=chart.end-span;chart.picked=Date.now();chart.draw();}
function chartZoom(f){if(!chart)return;const mid=(chart.start+chart.end)/2,span=Math.max(Core.DAY/4,Math.min(5*365*Core.DAY,(chart.end-chart.start)/f));chart.start=mid-span/2;chart.end=mid+span/2;chart.draw();}
function toggleFull(){document.body.classList.toggle('full-chart');setTimeout(()=>chart?.draw(),50);}
window.addEventListener('resize',()=>{if(page==='insights'){requestAnimationFrame(()=>{chart?.draw();weightChart?.draw();});}});
function drawChart(){
 if(!chart||!$('#pk-chart'))return;
 const ca=chart.canvas,w=ca.clientWidth,h=ca.clientHeight||270,dpr=devicePixelRatio||1;
 ca.width=w*dpr;ca.height=h*dpr;const c=ca.getContext('2d');c.scale(dpr,dpr);
 const surface=ca.closest('.card')||document.body,style=getComputedStyle(surface),dark=true,ink=style.getPropertyValue('--muted').trim()||'#bdd0dd',grid=style.getPropertyValue('--line').trim()||'#54718a',pink='#f48eb8',cardBg=style.getPropertyValue('--card').trim()||'#233e57',layer=k=>$('#layer-'+k)?.checked??(k!=='planned');
 const a=chart.start,b=chart.end,half=S.settings.half,ds=Core.doses(S.entries),scenario=Core.doses(S.entries.filter(e=>e.status!=='skipped').map(e=>({...e,status:'taken'})));
 const weights=layer('weight')?Core.weightDays(S.measurements,S.settings.weightMode).filter(r=>r.t>=a&&r.t<=b):[],right=layer('weight')?60:20,left=45,topY=22,bottom=h-47,W=w-left-right,H=bottom-topY,X=t=>left+(t-a)/(b-a)*W;
 chart.plotWidth=W;chart.weightPoints=weights.map(r=>({...r,x:X(r.t)}));
 let top=.5;for(let i=0;i<=240;i++){const t=a+(b-a)*i/240;top=Math.max(top,Core.amount(ds,t,half),layer('planned')?Core.amount(scenario,t,half):0);}
 const times=[...new Set(ds.filter(d=>d.t>=a&&d.t<=b).map(d=>d.t))];times.forEach(t=>top=Math.max(top,Core.amount(ds,t,half)));if(layer('planned'))scenario.filter(d=>d.t>=a&&d.t<=b).forEach(d=>top=Math.max(top,Core.amount(scenario,d.t,half)));top*=1.2;
 const Y=v=>bottom-v/top*H,wmin=weights.length?Math.floor(Math.min(...weights.map(r=>r.weight))-1):0,wmax=weights.length?Math.ceil(Math.max(...weights.map(r=>r.weight))+1):1,WY=v=>bottom-(v-wmin)/(wmax-wmin)*H;
 c.font='12px sans-serif';c.textAlign='left';c.fillStyle=ink;c.fillText('mg',left,12);if(layer('weight')){c.fillStyle=pink;c.fillText(unitLabel('weight'),w-right+9,12);}
 for(let i=0;i<=4;i++){const y=bottom-H*i/4;c.strokeStyle=grid;c.lineWidth=1;c.beginPath();c.moveTo(left,y);c.lineTo(w-right,y);c.stroke();c.fillStyle=ink;c.textAlign='right';c.fillText(fmt(top*i/4,1),left-7,y+3);if(weights.length){c.fillStyle=pink;c.textAlign='left';c.fillText(fmt(displayValue(wmin+(wmax-wmin)*i/4,'weight'),1),w-right+8,y+3);}}
 const ticks=w<500?3:5;
 for(let i=0;i<ticks;i++){const t=a+(b-a)*i/(ticks-1),d=new Date(t);c.fillStyle=ink;c.textAlign=i===0?'left':i===ticks-1?'right':'center';c.fillText(date(d),X(t),h-25);c.fillText(String(d.getFullYear()),X(t),h-11);}
 $('#chart-range').textContent=date(a)+' — '+date(b);
 c.save();c.beginPath();c.rect(left,topY,W,H);c.clip();
 function line(fn,color,dash=[],extra=[]){const ts=[a,b,...extra];for(let i=1;i<240;i++)ts.push(a+(b-a)*i/240);ts.sort((x,y)=>x-y);c.beginPath();c.strokeStyle=color;c.lineWidth=1.8;c.setLineDash(dash);ts.forEach((t,i)=>{if(i)c.lineTo(X(t),Y(fn(t-.1)));else c.moveTo(X(t),Y(fn(t-.1)));c.lineTo(X(t),Y(fn(t)));});c.stroke();c.setLineDash([]);}
 if(layer('model'))line(t=>Core.amount(ds,t,half),'#26aeb3',[],times);
 if(layer('planned'))line(t=>Core.amount(scenario,t,half),'#e78b78',[6,5],scenario.filter(d=>d.t>=a&&d.t<=b).map(d=>d.t));
 if(layer('daily'))line(t=>Core.mean(ds,t-Core.DAY,t,half),'#b784db',[4,3]);if(layer('trend'))line(t=>Core.mean(ds,t-7*Core.DAY,t,half),'#dca84b',[7,3]);const avg=Core.mean(ds,a,b,half);if(layer('average'))line(()=>avg,'#7b98ae',[2,4]);
 const now=Date.now();if(now>=a&&now<=b){c.strokeStyle=ink;c.setLineDash([3,4]);c.beginPath();c.moveTo(X(now),topY);c.lineTo(X(now),bottom);c.stroke();c.setLineDash([]);}
 if(layer('peaks'))times.forEach(t=>{const peak=Core.amount(ds,t,half),trough=Core.amount(ds,t-.1,half);c.fillStyle='#26aeb3';c.beginPath();c.arc(X(t),Y(peak),3.4,0,7);c.fill();c.fillStyle='#e58b7d';c.beginPath();c.arc(X(t),Y(trough),3,0,7);c.fill();if(times.length<10){c.font='12px sans-serif';c.textAlign='center';c.fillStyle=ink;c.fillText('P '+fmt(peak),X(t),Y(peak)-8);c.fillText('T '+fmt(trough),X(t),Y(trough)+15);}});
 // Weight is measured data on its own kg axis. No interpolation or invented daily points.
 weights.forEach(r=>{c.fillStyle=pink;c.beginPath();c.arc(X(r.t),WY(r.weight),4.5,0,Math.PI*2);c.fill();c.strokeStyle=cardBg;c.lineWidth=1;c.stroke();});
 // Place exact kg labels near measured points when space permits; selected day has priority.
 c.font='600 12px sans-serif';const boxes=[];
 const labelRows=[...weights].sort((x,y)=>Number(chart.picked!==null&&y.key===Core.dayKey(chart.picked))-Number(chart.picked!==null&&x.key===Core.dayKey(chart.picked)));
 labelRows.forEach(r=>{
  const text=Number(displayValue(r.weight,'weight')).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+unitLabel('weight'),bw=c.measureText(text).width+10,bh=18,px=X(r.t),py=WY(r.weight),bx=Math.max(left+2,Math.min(w-right-bw-2,px-bw/2));
  const selected=chart.picked!==null&&r.key===Core.dayKey(chart.picked);
  const candidates=[py-27,py+9,py-48,py+30];let by=candidates.find(y=>y>=topY+1&&y+bh<=bottom-1&&!boxes.some(b=>bx<b.x+b.w+4&&bx+bw+4>b.x&&y<b.y+b.h+3&&y+bh+3>b.y)&&!weights.some(other=>other!==r&&X(other.t)>bx-5&&X(other.t)<bx+bw+5&&WY(other.weight)>y-5&&WY(other.weight)<y+bh+5));
  if(by===undefined){if(!selected)return;by=Math.max(topY+1,Math.min(bottom-bh-1,py-27));}
  boxes.push({x:bx,y:by,w:bw,h:bh});c.strokeStyle=pink;c.lineWidth=.7;c.beginPath();c.moveTo(px,py);c.lineTo(Math.max(bx+4,Math.min(bx+bw-4,px)),by>py?by:by+bh);c.stroke();
  c.fillStyle=cardBg;c.beginPath();c.roundRect(bx,by,bw,bh,4);c.fill();c.fillStyle=pink;c.textAlign='center';c.fillText(text,bx+bw/2,by+12);
 });
 if(chart.picked!==null){const t=chart.picked;if(t>=a&&t<=b){c.strokeStyle='#e0aa59';c.beginPath();c.moveTo(X(t),topY);c.lineTo(X(t),bottom);c.stroke();}
 const wt=layer('weight')?weights.find(r=>r.key===Core.dayKey(t)):null;
 $('#chart-value').textContent=date(t)+' '+clock(t)+' · Model '+fmt(Core.amount(ds,t,half))+' mg · 24h avg '+fmt(Core.mean(ds,t-Core.DAY,t,half))+' mg'+(layer('weight')?(wt?' · Weight '+weightText(wt.weight)+(wt.count>1?' ('+weightModeLabel()+', '+wt.count+' readings)':' (1 reading)'):' · No weigh-in on this date'):'');
 }else $('#chart-value').textContent='View average '+fmt(avg)+' mg'+(layer('weight')?' · '+weights.length+' measured days · right '+unitLabel('weight')+' axis':'')+' · Tap a dot or drag to explore';
 c.restore();if(layer('planned')){c.fillStyle=ink;c.font='11px sans-serif';c.textAlign='right';c.fillText('Dashed coral: planned scenario',w-right,12);}
}
function profile(){const p=S.profile,w=latestWeight();return header('Made for you.','Your profile, goals and daily nutrition targets.')+card(`<div class="row"><span class="logo">${icon('user')}</span><div><h2>${esc(p.name||'Your profile')}</h2><span class="hint">${p.height?fmt(displayValue(p.height,'length'))+' '+unitLabel('length'):'Set up your details'}${w?' · '+weightText(w.values.weight)+' latest':''}</span></div></div>${button('Edit profile & nutrition','editProfile()')}${p.height&&w?`<div class="row spread" style="margin-top:16px"><span class="muted">Current BMI</span><b>${fmt(w.values.weight/Math.pow(p.height/100,2),1)}</b></div>`:''}${p.target?`<p class="hint">Goal weight · ${weightText(p.target)}</p>`:''}`)+card(`<h2>Health & imports</h2>${button('Connect Health Connect','connectHealth()','secondary')}${button('Import Eufy CSV','openFile("csv")','secondary')}${button('Body measurements','bodyHistory()','secondary')}${button('Backups & calendar import',"navigate('data')",'secondary')}`)+card(`<h2>Your preferences</h2>${button('Appearance & privacy',"navigate('settings')",'secondary')}${button('Equipment guide',"navigate('learn')",'secondary')}`);}
function editProfile(){const p=S.profile;modal('Profile & nutrition',`${field('p-name','Name',p.name||'')}${select('p-sex','Equation parameter',[['male','Male'],['female','Female']],p.sex||'male')}<div class="grid2">${field('p-age','Age · years',p.age||'','number')}${field('p-height','Height · cm',p.height||'','number')}</div><div class="grid2">${field('p-weight','Weight used for estimates · kg',p.weight||latestWeight()?.values.weight||'','number')}${field('p-target','Goal weight · kg',p.target||'','number')}</div>${select('p-activity','Typical activity',[[1.2,'Mostly sedentary'],[1.375,'Light activity'],[1.55,'Moderate activity'],[1.725,'High activity']],p.activity||1.375)}${field('p-deficit','Calorie deficit · % (0 = maintenance)',p.deficit??15,'number')}<label class="check"><input type="checkbox" id="p-keto" ${p.keto?'checked':''} onchange="ketoDefaults()">Keto lifestyle</label><div class="grid2">${field('p-protein','Protein target · g/day',p.protein||'','number')}${field('p-carbs','Total carbohydrate target · g/day',p.carbs||'','number')}</div><p class="hint">Protein has a separate range and target. Auto presets can be changed to Custom. Fat fills the remaining calorie budget. Keto is a preference, not a guarantee of ketosis. Carbohydrates here are total, not net. Energy uses the Mifflin–St Jeor estimate and your activity factor; no medication dose is calculated.</p><div id="macro-preview"></div>${button('Preview targets','previewMacros()','secondary')}${button('Save profile','saveProfile()')}`);}
function ketoDefaults(){if($('#p-keto').checked&&!val('p-carbs'))toast('Enter your own carbohydrate target. Protein stays unchanged.');}
function readProfile(){const p={name:val('p-name').trim(),sex:val('p-sex'),age:Core.positive(val('p-age'),'Age'),height:Core.positive(val('p-height'),'Height'),weight:Core.positive(val('p-weight'),'Weight'),target:val('p-target')?Core.positive(val('p-target'),'Goal weight'):null,activity:+val('p-activity'),deficit:Core.num(val('p-deficit')),protein:Core.positive(val('p-protein'),'Protein'),carbs:Core.positive(val('p-carbs'),'Carbohydrates'),keto:$('#p-keto').checked};if(p.age<18||p.age>110||p.height<100||p.height>250||p.weight<30||p.weight>400)throw Error('Check profile values. Energy estimates are intended for adults.');return p;}
function previewMacros(){try{const m=Core.macros(readProfile());$('#macro-preview').innerHTML=card(`<div class="eyebrow">Estimated daily target</div><div class="stat">${m.calories} kcal</div><p>Protein <b>${m.protein} g</b> · Carbs <b>${m.carbs} g</b> · Fat <b>${m.fat} g</b></p><p class="hint">Estimated maintenance: ${m.maintain} kcal · BMI ${fmt(m.bmi,1)}</p>`);}catch(e){formError(e);}}
function saveProfile(){try{const p=readProfile();Core.macros(p);if(change(()=>S.profile=p)){closeModal();render();toast('Profile saved.');}}catch(e){formError(e);}}
function settings(){let lock=false;if(window.Native)lock=Native.isLockEnabled();return header('Your look. Your privacy.','Tailor Reta Log to feel like your own.')+card(`<div class="eyebrow">Appearance</div><h2>Choose your atmosphere</h2><div class="chipbar">${['light','dark','system','midnight','forest','slate'].map(t=>`<button class="${S.settings.theme===t?'on':''}" onclick="setSetting('theme','${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><label>Accent palette</label>${accentPalette()}<p class="hint">Accents adapt to each theme for readable text. Yellow uses a darker gold in light themes.</p><label class="check"><input type="checkbox" ${S.settings.detailed?'checked':''} onchange="setSetting('detailed',this.checked)">Detailed journal view</label>${[['showWeight','Weight card'],['showMacros','Nutrition targets card'],['showEstimate','Model estimate card']].map(([k,l])=>`<label class="check"><input type="checkbox" ${S.settings[k]?'checked':''} onchange="setSetting('${k}',this.checked)">${l}</label>`).join('')}`)+card(`<div class="row">${icon('shield')}<h2>Private by design</h2></div><label class="check"><input type="checkbox" ${lock?'checked':''} onchange="setLock(this.checked)">Biometric lock</label><p class="hint">When enabled, unlock with biometrics or your device credential before seeing any data. Reta Log locks immediately when you leave. Screenshots and recent-app previews are hidden while the lock is enabled.</p>${button('Lock now','lockNow()','secondary')}`)+card(`<h2>Model settings</h2>${field('half','Assumed elimination half-life · days',S.settings.half,'number')}${button('Save model assumption','saveHalf()','secondary')}<p class="hint">Default: 6 days. This is a simplified educational estimate, not personalised pharmacokinetics. Changing the assumption does not change your recorded doses.</p>`)+card(`<div class="eyebrow">Reta Log · 2.0.1</div><p class="hint">Offline personal journal. Health Connect and calendar access happen on your phone with permission. Your data is not sent to a server by this app.</p>`);}
function setSetting(k,v){if(change(()=>S.settings[k]=v))render();}function saveHalf(){try{const h=Core.positive(val('half'));if(h<.5||h>30)throw Error('Use a half-life from 0.5 to 30 days.');if(change(()=>S.settings.half=h))toast('Model assumption saved.');}catch(e){toast(e.message);}}
function setLock(v){if(window.Native)Native.setLockEnabled(v);else toast('Biometric security is available in the Android app.');}function lockNow(){if(window.Native)Native.lockNow();else toast('Available on Android.');}
function inventory(){return header('Your supplies','Keep vials and pen cartridges organised.')+button('+ Add a supply','editVial()')+S.vials.map(v=>{const {used}=Core.supplyBalance(v,S.entries);return card(`${v.type==='cartridge'?penArt():vialArt()}<div class="row spread"><h2>${esc(v.name)}</h2><span class="pill">${v.type==='cartridge'?'Pen cartridge':'Vial'}</span></div><p class="hint">${esc(v.state)} · ${fmt(v.mg)} mg declared</p><div class="stat">${fmt(Math.max(0,v.mg-used))} mg remaining</div><p class="hint">Estimate from linked taken entries only.${used>v.mg?' Recorded use exceeds declared supply.':''}</p>${v.volume?`<p class="hint">Final volume ${fmt(v.volume)} mL · ${fmt(v.mg/v.volume)} mg/mL</p>`:''}${v.prepared?`<p class="hint">Preparation date: ${esc(v.prepared)}</p>`:''}${supplyHistory(v)}${button('Edit supply',`editVial('${v.id}')`,'secondary')}`,'supply-card','supply-'+v.id);}).join('')+(!S.vials.length?card(`<div class="empty">${vialArt()}<h2>A place for every supply</h2><p class="hint">Link each journal entry to its vial or cartridge.</p></div>`):'');}
function supplyHistory(v){
 const now=Date.now(),rows=S.entries.filter(e=>e.vial===v.id&&(!e.status||e.status==='taken')&&Date.parse(e.at)<=now).sort(Core.entryOrder),balance=Core.supplyBalance(v,S.entries,now);
 return `<div class="supply-history"><div class="row spread"><h3>Injection history</h3><span class="pill">${rows.length} ${rows.length===1?'entry':'entries'}</span></div><div class="stat">${fmt(balance.used)} <small>mg injected so far</small></div>${rows.length?`<div class="supply-history-list">${rows.map(e=>`<div class="list-item row spread"><div><b>${date(e.at)}</b><div class="hint">${new Date(e.at).toLocaleDateString('en-GB',{weekday:'long'})} · ${clock(e.at)}</div></div><b>${fmt(e.mg)} mg</b></div>`).join('')}</div>`:'<p class="hint">No confirmed injections linked to this supply yet.</p>'}<p class="hint">Confirmed journal entries linked to this ${v.type==='cartridge'?'cartridge':'vial'}. Planned and skipped entries are excluded.</p></div>`;
}
function editVial(id){const v=S.vials.find(v=>v.id===id)||{};modal('Supply details',`${field('v-name','Label',v.name||'')}${select('v-type','Container',[['vial','Vial · lyophilised retatrutide'],['cartridge','Pen cartridge']],v.type||'vial')}${select('v-state','Current state',[['Lyophilised','Lyophilised'],['Prepared solution','Prepared solution'],['Prefilled solution','Prefilled solution']],v.state||'Lyophilised')}${field('v-mg','Declared total amount · mg',v.mg||'','number')}${field('v-volume','Final solution volume · mL (optional)',v.volume||'','number')}${field('v-prepared','Preparation date (optional)',v.prepared||'','date')}${field('v-note','Notes',v.note||'')}<p class="hint">Store label information only. This does not verify content, sterility, storage life or pen compatibility.</p>${button('Save supply',`saveVial('${id||''}')`)}${id?button('Remove supply',`removeVial('${id}')`,'danger'):''}`);}
function saveVial(id){try{const v={id:id||uid(),name:val('v-name').trim(),type:val('v-type'),state:val('v-state'),mg:Core.positive(val('v-mg')),volume:val('v-volume')?Core.positive(val('v-volume')):null,prepared:val('v-prepared'),note:val('v-note')};if(!v.name)throw Error('Give the supply a label.');if(change(()=>{S.vials=S.vials.filter(v=>v.id!==id);S.vials.push(v);},true)){closeModal();render();toast('Supply saved.',true);}}catch(e){formError(e);}}
function removeVial(id){if(confirm('Remove this supply? Linked journal entries will remain.')&&change(()=>{S.vials=S.vials.filter(v=>v.id!==id);},true)){closeModal();render();toast('Supply removed.',true);}}
function dataPage(){return header('Your data, in your hands.','Import, export and keep a safe copy.')+card(`<h2>Bring your history</h2>${button('Import Eufy CSV','openFile("csv")')}${button('Read device calendar','openCalendar()','secondary')}${button('Import calendar file (.ics)','openFile("ics")','secondary')}${button('Read Health Connect','connectHealth()','secondary')}<p class="hint">EufyLife: Me → Data → Export All Data. The CSV is emailed to you. Review column mapping and dates before importing.</p>`)+card(`<h2>Backup & reports</h2>${button('Export complete backup','exportBackup()','secondary')}${button('Restore backup','openFile("backup")','secondary')}${button('Export journal CSV','exportJournal()','secondary')}${button('Create PDF report','exportReport()','secondary')}<p class="hint">Exports contain readable health data. Choose a private destination. Restoring a backup replaces the journal after confirmation.</p>`)+card(`<h2>Import history</h2>${S.batches.length?[...S.batches].reverse().map(b=>`<div class="list-item"><b>${esc(b.source)}</b><p class="hint">${date(b.at)} · ${b.count} records</p>${button('Undo this import',`undoImport('${b.id}')`,'secondary')}</div>`).join(''):'<p class="muted">No imports yet.</p>'}`);}
function openFile(kind){if(window.Native)Native.openFile(kind);else{const el=document.createElement('input');el.type='file';el.accept=kind==='csv'?'.csv,text/csv':kind==='ics'?'.ics,text/calendar':'.json,application/json';el.onchange=async()=>{if(el.files[0])receiveFile(kind,await el.files[0].text());};el.click();}}
function receiveFile(kind,text){try{if(kind==='ics'){receiveCalendar(Core.parseICS(text));}else if(kind==='csv'){csvData=Core.parseCSV(text);showCsvMapping();}else{const incoming=Core.validateStore(JSON.parse(text));if(confirm('Replace this journal with the selected backup? Export a current backup first if you need to keep it.')){if(change(()=>S={...defaults(),...incoming,settings:{...defaults().settings,...incoming.settings}},true)){if(window.Native)Native.scheduleReminders(JSON.stringify(S.reminders));closeModal();render();toast('Backup restored.',true);}}}}catch(e){toast(e.message);}}
function csvColumnSamples(i){return csvData.rows.slice(0,12).map(r=>r[i]).filter(v=>String(v??'').trim());}
function showCsvMapping(){const headers=csvData.headers,eufy=Core.isEufyCsv(headers,csvData.rows),options=[['','Ignore'],['timestamp','Date & Time (Timestamp)'],['date','Date'],['time','Separate Time'],['person','Profile / Family Member'],...Object.entries(Core.metricNames)],guesses=headers.map((h,i)=>/user|profile|member|name/i.test(h)?'person':Core.guessHeader(h,csvColumnSamples(i))),ambiguous=headers.some((_,i)=>csvColumnSamples(i).some(Core.isAmbiguousDate)),timeIndex=guesses.indexOf('timestamp'),sample=timeIndex>=0?csvColumnSamples(timeIndex)[0]:'';let banner='<p class="hint">Confirm what each column means. Only mapped values are imported. Empty values remain missing.</p>';if(eufy){banner='<div class="import-row"><b>Eufy CSV detected</b><p class="hint">'+headers.length+' columns found · '+csvData.rows.length+' measurements. Recognised fields are mapped automatically; review them, then import.</p>';if(sample){const parsed=Core.parseDate(sample);banner+='<p class="hint">Timestamp preview<br>Source: '+esc(sample)+'<br>Parsed: '+esc(date(parsed)+' · '+clock(parsed))+'</p>';}banner+='</div>';}const order=ambiguous?select('csv-order','Date order for dates like 09/10/2026',[['DMY','Day / Month / Year'],['MDY','Month / Day / Year']],'DMY'):'';const fields=headers.map((h,i)=>select('map-'+i,esc(h),options,guesses[i])+'<div class="hint">Example: '+esc(csvColumnSamples(i)[0]||'empty')+'</div>').join('');modal(eufy?'Map Eufy columns':'Map CSV columns',banner+order+select('csv-unit','Mass units in file',[['kg','Kilograms'],['lb','Pounds']],'kg')+'<p class="hint">Water, fat and protein fields marked % must contain percentages, not fractions. BMI, BMR and pulse keep their original units.</p>'+fields+field('csv-person','Only this profile (exact value, if a profile column exists)')+button('Preview import','previewCsv()'));}
function previewCsv(){try{const map=csvData.headers.map((_,i)=>val('map-'+i)),keys=map.filter(Boolean),timestampCol=map.indexOf('timestamp'),dateCol=map.indexOf('date');if(timestampCol<0&&dateCol<0)throw Error('Map a date or timestamp column.');if(new Set(keys).size!==keys.length)throw Error('Map each field only once.');const personCol=map.indexOf('person'),filter=val('csv-person').trim(),candidates=[],errors=[],identityCounts=new Map(),unit=val('csv-unit'),order=$('#csv-order')?.value||'DMY',eufy=Core.isEufyCsv(csvData.headers,csvData.rows);csvData.rows.forEach((row,i)=>{if(filter&&personCol>=0&&row[personCol]!==filter)return;try{const timeCol=map.indexOf('time'),sourceTime=timestampCol>=0?row[timestampCol]:row[dateCol]+(timeCol>=0&&row[timeCol]?' '+row[timeCol]:''),at=Core.parseDate(sourceTime,order);if(Date.parse(at)>Date.now()+60000)throw Error('Future measurement');const values={};map.forEach((k,j)=>{if(!k||['timestamp','date','time','person'].includes(k)||!String(row[j]??'').trim())return;if(k==='bodyType'){values[k]=String(row[j]).trim();return;}const clean=String(row[j]).trim().replace(/\s*(kg|lbs?|%|kcal|bpm)\s*$/i,'').trim(),n=Core.num(clean);if(!Number.isFinite(n)||n<0)throw Error('Invalid '+k);if(['fat','water','protein','subcutaneous','musclePercent','bonePercent'].includes(k)&&n>100)throw Error('Percentage over 100');values[k]=unit==='lb'&&['weight','lean','muscle','bone','skeletal','fatMass','waterMass'].includes(k)?n*.45359237:n;});if(!Object.keys(values).length)throw Error('No measurement fields');const person=personCol>=0?String(row[personCol]||'').trim():'',base=Core.csvIdentity(eufy?'eufy':'csv',person,at,values),occurrence=identityCounts.get(base)||0;identityCounts.set(base,occurrence+1);candidates.push({id:uid(),at,values,source:eufy?'Eufy CSV':'CSV import',profile:person,externalId:base+':'+occurrence});}catch(e){errors.push('Row '+(i+2)+': '+e.message);}});if(!candidates.length)throw Error(errors.slice(0,4).join('\n')||'No rows matched the selected profile.');importData={source:eufy?'Eufy CSV':'CSV import',kind:'measurements',rows:candidates};showMeasurementPreview(errors);}catch(e){formError(e);}}
function measurementDuplicate(m){return S.measurements.some(x=>m.externalId?x.externalId===m.externalId:(x.at===m.at&&Object.entries(m.values).every(([k,v])=>String(x.values[k])===String(v))));}
function showMeasurementPreview(errors=[]){const rows=importData.rows,duplicates=rows.filter(measurementDuplicate).length;modal('Review body data',`<p><b>${rows.length}</b> records found · <b>${duplicates}</b> existing duplicates skipped.</p>${errors.length?`<div class="error" style="display:block">${errors.length} rows could not be read. They will be skipped.<br>${errors.slice(0,8).map(esc).join('<br>')}</div>`:''}<p class="hint">Preview shows up to 30 rows. Confirm that dates, units and profile are correct.</p>${rows.slice(0,30).map(m=>`<div class="import-row"><b>${date(m.at)} · ${clock(m.at)}</b><p class="hint">${Object.entries(m.values).map(([k,v])=>esc(Core.metricNames[k]||k)+': '+(k==='bodyType'?esc(v):fmt(v))).join(' · ')}</p><span class="badge">${esc(m.source)}</span></div>`).join('')}${button('Import '+(rows.length-duplicates)+' new records','commitMeasurements()')}`);}
function commitMeasurements(){const b={id:uid(),at:new Date().toISOString(),source:importData.source,count:0};if(change(()=>{for(const row of importData.rows){if(!measurementDuplicate(row)){S.measurements.push({...row,batch:b.id});b.count++;}}if(b.count)S.batches.push(b);},true)){closeModal();render();toast(b.count+' records imported.',true);}}
function undoImport(id){const b=S.batches.find(b=>b.id===id);if(!b||!confirm('Remove every record from this import, including any edited records in it? Other records remain.'))return;if(change(()=>{S.measurements=S.measurements.filter(m=>m.batch!==id);S.entries=S.entries.filter(m=>m.batch!==id);S.batches=S.batches.filter(b=>b.id!==id);},true)){render();toast('Import removed.',true);}}
function openCalendar(){if(window.Native)Native.openCalendar();else toast('Calendar import is available on Android.');}
function receiveCalendars(rows){if(!rows.length){toast('No synced calendars found on this device.');return;}modal('Import calendar history',`${select('calendar-id','Choose a synced calendar',rows.map(r=>[r.id,r.name+' · '+r.account]),rows[0].id)}${field('calendar-days','Look back · days',42,'number')}<p class="hint">Reads titles and descriptions containing Reta, retatrutid or retatrutide. Your calendar will not be changed.</p>${button('Find entries','queryCalendar()')}`);}
function queryCalendar(){try{const days=Core.positive(val('calendar-days'));if(days>3660)throw Error('Choose at most 3,660 days.');Native.queryCalendar(val('calendar-id'),Math.round(days));toast('Reading selected calendar…');}catch(e){formError(e);}}
function receiveCalendar(rows){calendarRows=rows;if(!rows.length){toast('No matching events found in that calendar and period.');return;}modal('Review calendar entries',`<p class="hint">Select only events that represent amounts actually taken. Confirm or correct each amount. Planned calendar events are not proof of an injection.</p>${rows.map((r,i)=>{const matches=(r.title+' '+r.description).match(/\b\d+(?:[.,]\d+)?\s*mg\b/gi)||[];const unique=[...new Set(matches.map(m=>Core.num(m.replace(/mg/i,''))))];const mg=unique.length===1?unique[0]:'';r.defaultMg=mg;return `<div class="import-row"><label class="check"><input type="checkbox" id="cal-check-${i}"><b>${esc(r.title)}</b></label><p class="hint">${esc(r.description||'')}</p>${field('cal-at-'+i,r.allDay?'All-day event · confirm actual time':'Date & time',local(r.at),'datetime-local')}${field('cal-mg-'+i,'Amount · mg',mg,'number')}${unique.length!==1?'<p class="hint">Amount missing or ambiguous. Please enter it.</p>':''}</div>`;}).join('')}${button('Import selected taken entries','commitCalendar()')}`);}
function commitCalendar(){try{const batch={id:uid(),at:new Date().toISOString(),source:'Device calendar',count:0},rows=[];calendarRows.forEach((r,i)=>{if(!$('#cal-check-'+i).checked)return;const at=new Date(val('cal-at-'+i)).toISOString(),mg=Core.positive(val('cal-mg-'+i));if(Date.parse(at)>Date.now())throw Error('Taken entries cannot be future-dated.');rows.push({id:uid(),at,mg,site:'',note:r.title,status:'taken',source:'Calendar',externalId:r.externalId,batch:batch.id});});if(!rows.length)throw Error('Select at least one confirmed taken entry.');if(change(()=>{rows.forEach(e=>{const dup=S.entries.some(x=>x.externalId===e.externalId||(+x.mg===e.mg&&x.at===e.at));if(!dup){S.entries.push(e);batch.count++;}});if(batch.count)S.batches.push(batch);},true)){closeModal();render();toast(batch.count+' entries imported. Duplicates skipped.',true);}}catch(e){formError(e);}}
function connectHealth(){if(window.Native)Native.connectHealth();else toast('Health Connect is available in the Android app on Android 14+.');}
function receiveHealth(payload){const rows=payload.rows||[];if(!rows.length){toast('No readable measurements found. '+(payload.warnings||[]).join(' '));return;}importData={source:'Health Connect',kind:'measurements',rows};showMeasurementPreview(payload.warnings||[]);}
function bodyHistory(){modal('Body measurements',`${button('Add a measurement','editMeasurement()')}${[...S.measurements].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).map(m=>`<div class="import-row"><div class="row spread"><b>${date(m.at)} · ${clock(m.at)}</b><button class="link" onclick="editMeasurement('${m.id}')">Edit</button></div><p class="hint">${esc(m.source||'Manual')}</p><div class="grid2">${Object.entries(m.values).map(([k,v])=>`<div><label>${esc(Core.metricNames[k]||k)}</label><b>${k==='bodyType'?esc(v):fmt(v)}</b></div>`).join('')}</div></div>`).join('')}`);}
function editMeasurement(id){const m=S.measurements.find(m=>m.id===id)||{values:{}};modal('Body measurement',`${field('measure-at','Date & time',local(m.at),'datetime-local')}<p class="hint">Body composition values are estimates reported by your scale. Leave unavailable fields empty.</p><div class="grid2">${Object.entries(Core.metricNames).map(([k,n])=>field('measure-'+k,n,m.values[k]??'',k==='bodyType'?'text':'number')).join('')}</div>${button('Save measurement',`saveMeasurement('${id||''}')`)}${id?button('Delete measurement',`removeMeasurement('${id}')`,'danger'):''}`);}
function saveMeasurement(id){try{const values={};Object.keys(Core.metricNames).forEach(k=>{const v=val('measure-'+k);if(v.trim())values[k]=k==='bodyType'?v:Core.positive(v,k);});if(!Object.keys(values).length)throw Error('Enter at least one value.');const at=new Date(val('measure-at')).toISOString();if(Date.parse(at)>Date.now())throw Error('Measurement cannot be in the future.');const old=S.measurements.find(m=>m.id===id);if(change(()=>{S.measurements=S.measurements.filter(m=>m.id!==id);S.measurements.push({...old,id:id||uid(),at,values,source:old?.source||'Manual'});},true)){closeModal();render();toast('Measurement saved.',true);}}catch(e){formError(e);}}
function removeMeasurement(id){if(confirm('Delete this measurement?')&&change(()=>S.measurements=S.measurements.filter(m=>m.id!==id),true)){closeModal();render();toast('Measurement deleted.',true);}}
function saveFile(name,mime,text){if(window.Native)Native.exportText(name,mime,text);else{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();URL.revokeObjectURL(a.href);}}
function exportBackup(){saveFile('Reta-Log-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json',JSON.stringify(S,null,2));}
function exportJournal(){const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';saveFile('Reta-Log-journal.csv','text/csv',[['Date','Amount mg','Status','Site','Notes','Source'],...S.entries.map(e=>[e.at,e.mg,e.status||'taken',e.site,e.note,e.source])].map(r=>r.map(q).join(',')).join('\r\n'));}
function exportReport(){if(window.Native)Native.exportReport(JSON.stringify(S));else toast('PDF export is available in the Android app.');}
function reminders(){return header('A gentle reminder.','Your own schedule. Private notifications.')+button('+ Create reminder','editReminder()')+card(`<p class="hint">Notifications say “Your reminder is ready” without a substance name or amount. They never mark an entry as taken. Delivery can be delayed by Android battery settings.</p>`)+S.reminders.map(r=>card(`<div class="row spread"><h2>${esc(r.label)}</h2><span class="pill">${r.enabled?'Active':'Off'}</span></div><p>${esc(r.time)} · ${r.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d]).join(', ')}</p>${button('Edit reminder',`editReminder('${r.id}')`,'secondary')}`)).join('');}
function editReminder(id){const r=S.reminders.find(r=>r.id===id)||{days:[],time:'09:00',label:'Personal reminder',enabled:true};modal('Reminder',`${field('r-label','Private in-app label',r.label)}${field('r-time','Time',r.time,'time')}<label>Repeat on</label><div class="grid2">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label class="check"><input type="checkbox" id="r-day-${i}" ${r.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div><label class="check"><input type="checkbox" id="r-enabled" ${r.enabled?'checked':''}>Enabled</label>${button('Save reminder',`saveReminder('${id||''}')`)}${id?button('Delete reminder',`removeReminder('${id}')`,'danger'):''}`);}
function saveReminder(id){try{const days=[0,1,2,3,4,5,6].filter(d=>$('#r-day-'+d).checked);if(!days.length||!val('r-time'))throw Error('Choose a time and at least one day.');const r={id:id||uid(),label:val('r-label')||'Personal reminder',time:val('r-time'),days,enabled:$('#r-enabled').checked};if(change(()=>{S.reminders=S.reminders.filter(r=>r.id!==id);S.reminders.push(r);})){if(window.Native)Native.scheduleReminders(JSON.stringify(S.reminders));closeModal();render();toast('Reminder saved.');}}catch(e){formError(e);}}
function removeReminder(id){if(confirm('Delete reminder?')&&change(()=>S.reminders=S.reminders.filter(r=>r.id!==id))){if(window.Native)Native.scheduleReminders(JSON.stringify(S.reminders));closeModal();render();}}
function learn(){return header('Small details. Clear answers.','Your illustrated equipment guide.')+card(`<div class="eyebrow">01 / Volume</div><h2>Meet the syringe</h2>${syringeArt(1)}<p><b>mL</b> tells you the volume of liquid, not the amount of medicine in mg.</p><div class="chipbar">${[.3,.5,1,3].map(n=>`<button onclick="showSyringeGuide(${n})">${n} mL</button>`).join('')}</div><p class="hint">Insulin syringes may be marked in insulin units. A 1 mL syringe is not necessarily an insulin syringe. Check its label and graduations.</p>`)+card(`<div class="eyebrow">02 / Length & thickness</div><h2>Read a needle label</h2>${needleArt()}<div class="stats"><div><div class="stat">4–6 mm</div><p class="hint">Illustrated needle lengths. Drawings are not actual screen size.</p></div><div><div class="stat">31G · 32G</div><p class="hint">Gauge describes thickness. A higher number means a thinner needle.</p></div></div><p><b>32G × 4 mm</b> means a 32-gauge needle, 4 millimetres long. It says nothing about dose or syringe volume.</p><p class="hint">Fixed needles are attached to the syringe. Detachable needles use a connector such as Luer slip or Luer lock. Pen needles have a different attachment; compatibility must be checked for the exact device.</p>`)+card(`<div class="eyebrow">03 / Pen devices</div><h2>A pen is a system</h2>${penArt()}<p>A <b>prefilled pen</b> comes with a preparation inside. A <b>reusable pen</b> accepts specified cartridges and compatible pen needles.</p><p class="hint">A cartridge fitting physically does not prove compatibility. Cartridge capacity is not the amount delivered per click. There is no universal “mg per click”.</p>`)+card(`<div class="eyebrow">04 / Units</div><h2>Four labels, four meanings</h2><div class="list-item"><b>mg</b> · mass of a substance</div><div class="list-item"><b>mL</b> · volume of a solution</div><div class="list-item"><b>Insulin units</b> · medicine-specific scale; U-100 and U-40 scales differ</div><div class="list-item"><b>Pen clicks</b> · mechanism-specific increments, not a universal dose</div><p class="hint">This guide explains labels, not how to prepare or inject retatrutide. Use device instructions and professional advice for equipment selection. Single-use needles must not be shared or reused.</p><div class="sources hint">Sources: <a href="https://www.embecta.com/">embecta</a> · <a href="https://www.bd.com/">BD</a></div>`);}
function showSyringeGuide(cap){modal(cap+' mL syringe',syringeArt(cap)+`<p>This drawing uses a millilitre scale. The smallest mark on a real syringe depends on its model.</p><p class="hint">Capacity is ${cap} mL. Never interpret this as ${cap} mg.</p>`);}
function onboard(){modal('Welcome to Reta Log',`${vialArt()}<h2>A calmer way to keep track.</h2><p class="muted">Your journal, body trends and visual tools — stored on your phone.</p>${button('Set up my profile','finishOnboarding(true)')}${button('Enable biometric lock','setLock(true)','secondary')}${button('Explore first','finishOnboarding(false)','secondary')}<p class="hint">This app keeps records and shows estimates. It does not recommend medication doses.</p>`);}
function finishOnboarding(profileFirst){if(change(()=>S.onboarded=true)){closeModal();if(profileFirst)editProfile();}}
function nativeEvent(name,data){if(name==='error')toast(data);if(name==='file')receiveFile(data.kind,data.text);if(name==='calendars')receiveCalendars(data);if(name==='calendar')receiveCalendar(data);if(name==='health')receiveHealth(data);if(name==='lock'){if(page==='settings')render();toast(data);}if(name==='saved')toast(data);}
window.nativeEvent=nativeEvent;
function progressPanel(){const p=Core.progress(S.entries,selectedWeightRecords()),delta=p.weightChange,percent=delta===null?null:delta/p.firstWeight*100;return card(`<div class="row spread"><div class="eyebrow">Your journey in numbers</div><span class="pill">${p.days} days</span></div><div class="stats"><div><div class="big">${delta===null?'—':fmt(Math.abs(delta))}<small> kg</small></div><div class="hint">${delta===null?'Add two weight records':delta<0?'Lost since journey baseline':delta>0?'Gained since journey baseline':'No net change'}${percent===null?'':' · '+fmt(Math.abs(percent),1)+'%'}</div></div><div><div class="stat">${p.entries}</div><div class="hint">Taken entries · ${p.daysWithEntries} calendar days</div><div class="stat" style="margin-top:10px">${fmt(p.totalMg)} mg</div><div class="hint">Total recorded amount</div></div></div><hr><div class="row spread"><span class="hint">Last 7 days · average recorded weight</span><b>${p.recentMean===null?'—':fmt(p.recentMean)+' kg'}</b></div>${p.recentMean!==null&&p.previousMean!==null?`<p class="hint">${fmt(p.recentMean-p.previousMean)} kg versus the previous 7-day average.</p>`:''}<p class="hint">${p.firstDose===null?'Add your first confirmed dose to start your journey.':'Journey starts '+dayDate(p.firstDose)+'. Weeks start on the same weekday as your first dose.'} ${p.baselineAt?'Weight baseline: '+dayDate(p.baselineAt)+', the first available weight on or after your starting day. Earlier weights stay in Body / weight trend.':'Add weight measurements on or after your first dose.'}</p><div class="chipbar"><button class="on" id="week-period" onclick="showPeriods('weekly')">By week</button><button id="month-period" onclick="showPeriods('monthly')">By month</button></div><div id="period-table">${periodRows(p.weekly)}</div>`);}
function periodRows(rows){if(!rows.length)return '<p class="hint">Import your weight history to see this view.</p>';return [...rows].reverse().slice(0,24).map(r=>`<div class="list-item row spread"><div><b>${r.number?'Week '+r.number+' · ':''}${dayDate(r.start)}${r.end?' — '+dayDate(r.end-1):''}</b><div class="hint">${r.count} measurements · ${fmt(r.from)} → ${fmt(r.to)} kg</div></div><b style="color:${r.change!==null&&r.change<0?'var(--accent)':'var(--muted)'}">${r.change===null?'—':(r.change>0?'+':'')+fmt(r.change)+' kg'}</b></div>`).join('')+'<p class="hint">Change = last minus first recorded weight within each period. A single measurement cannot establish a change; periods without measurements are omitted.</p>';}
function showPeriods(period){const p=Core.progress(S.entries,selectedWeightRecords());$('#period-table').innerHTML=periodRows(p[period]);$('#week-period').classList.toggle('on',period==='weekly');$('#month-period').classList.toggle('on',period==='monthly');}
function forecastPanel(){
 const f=Core.forecast(selectedWeightRecords(),S.profile.target),messages={
 'no-target':'Set your goal weight in Profile to see a projection.',
 'insufficient':'Add at least 5 days of weigh-ins spanning 14 days within the last 28 days.',
 'stale':'Add a recent weigh-in. Your latest weight is more than 7 days old.',
 'no-decline':'Your recent trend is stable or rising. No arrival date is projected.',
 'distant':'The projected date is more than two years away; this trend is too slow for a useful countdown.',
 'reached':'Your recent selected-weight average is at or below your goal.'};
 return card(`<div class="row spread"><div class="eyebrow">Your goal horizon</div><span class="badge">TREND ESTIMATE</span></div>${f.status==='ready'?`<div class="big">${f.days}<small> days</small></div><p>To <b>${fmt(f.target)} kg</b> · around <b>${dayDate(f.at)}</b></p><div class="row spread"><span class="hint">Recent pace</span><b>${fmt(f.weekly)} kg / week</b></div><p class="hint">Based on ${f.daysObserved} selected daily weights over ${f.span} days. Starting weight: recent average ${fmt(f.current)} kg.</p>`:`<h2>${f.status==='reached'?'Goal reached':'A clearer horizon takes time'}</h2><p class="muted">${messages[f.status]}</p>`}<p class="hint">Projects your recent weight trend forward at a constant rate. Water changes and plateaus can shift the date. This is not a promise or a medication recommendation.</p>`);
}
const originalInsights=insights;insights=function(){return originalInsights()+forecastPanel()+progressPanel();};

// Boot occurs after 1.6 extensions load.
